"""LangChain callback handler for PRISMtrace span collection."""

from __future__ import annotations

import atexit
import json
import os
import threading
import uuid
import weakref
from datetime import datetime, timezone
from typing import Any, Optional

import httpx
from ._config import DEFAULT_HOST as _SHARED_DEFAULT_HOST
from ._session import resolve_session

try:
    from langchain_core.callbacks import BaseCallbackHandler
    from langchain_core.outputs import LLMResult
    from langchain_core.agents import AgentAction, AgentFinish

    _HAS_LANGCHAIN = True
except ImportError:
    try:
        from langchain.callbacks.base import BaseCallbackHandler
        from langchain.schema import LLMResult, AgentAction, AgentFinish

        _HAS_LANGCHAIN = True
    except ImportError:
        _HAS_LANGCHAIN = False
        BaseCallbackHandler = object  # type: ignore[assignment,misc]


DEFAULT_HOST = _SHARED_DEFAULT_HOST

# Keep weak refs so atexit can flush without retaining every handler forever.
_LIVE_HANDLERS: "weakref.WeakSet[PRISMtraceCallbackHandler]" = weakref.WeakSet()
_ATEXIT_REGISTERED = False

# Bucket used by direct writes to ``handler._spans`` and by ``handler.trace_id``.
# Those were plain attributes before per-run state existed; keeping one bucket
# under a reserved key means code that pokes at them still works, while real
# callback traffic is partitioned by LangChain run id and cannot collide with it.
_LEGACY_RUN_KEY = "__prismtrace_legacy__"


def _register_atexit() -> None:
    global _ATEXIT_REGISTERED
    if _ATEXIT_REGISTERED:
        return

    def _flush_all() -> None:
        for handler in list(_LIVE_HANDLERS):
            try:
                handler.flush()
            except Exception:
                pass

    atexit.register(_flush_all)
    _ATEXIT_REGISTERED = True


def _resolve_host(endpoint: Optional[str], host: Optional[str]) -> str:
    raw = (
        host
        or endpoint
        or os.getenv("PRISMTRACE_HOST")
        or os.getenv("PRISMTRACE_ENDPOINT")
        or DEFAULT_HOST
    )
    return str(raw).rstrip("/")


class _RunState:
    """Everything one LangChain run owns, so two runs cannot share any of it.

    trace_id, the completed-span buffer, the open-span map and the chain depth
    all used to be single attributes on the handler. Two concurrent requests
    through one shared handler therefore drove a single depth counter: the
    first run to finish decremented it to 1 and did not flush, the second
    decremented it to 0 and flushed BOTH runs' spans under one trace_id. The
    first run did not get a late trace, it got no trace of its own at all.
    """

    __slots__ = ("trace_id", "session_id", "spans", "open_spans", "depth", "agent_open")

    def __init__(self, session_id: str) -> None:
        self.trace_id = str(uuid.uuid4())
        # Resolved once, when the run starts. Not at flush: flush often happens
        # at interpreter exit, when no ambient session is in scope any more.
        self.session_id = session_id
        self.spans: list[dict] = []
        self.open_spans: dict[str, dict] = {}
        self.depth = 0
        # Chain run id -> the span id of that chain's currently open agent
        # action. LangChain gives an agent action no run id of its own, so the
        # handler mints one and has to remember it to close it (ADR-0147).
        self.agent_open: dict[str, str] = {}


class PRISMtraceCallbackHandler(BaseCallbackHandler):
    """LangChain callback handler that collects spans and sends them to PRISMtrace.

    Auth uses ``X-PRISMtrace-Key`` (platform contract since SDK v0.2.0).
    Constructor args may be omitted when the matching ``PRISMTRACE_*`` env vars
    are set.

    One handler is safe to share across concurrent runs: per-run state is keyed
    by the LangChain root run id, so two requests in flight at once produce two
    traces instead of one interleaved one.

    ``session_id`` may be left out and supplied ambiently instead, which is what
    a multi-agent app wants::

        handler = PRISMtraceCallbackHandler(api_key=..., project_id=...)

        with prismtrace.session(f"chat-{user_id}"):
            researcher.invoke(...)
            writer.invoke(...)

    A ``session_id`` passed here still wins over the ambient one.
    """

    def __init__(
        self,
        api_key: Optional[str] = None,
        project_id: Optional[str] = None,
        endpoint: Optional[str] = None,
        host: Optional[str] = None,
        session_id: Optional[str] = None,
        agent_name: Optional[str] = None,
        source: str = "langchain",
        timeout: int = 10,
    ):
        if not _HAS_LANGCHAIN:
            raise ImportError(
                "langchain is required. Install with: pip install langchain-core"
            )
        super().__init__()
        resolved_key = (api_key or os.getenv("PRISMTRACE_API_KEY") or "").strip()
        resolved_project = (
            project_id or os.getenv("PRISMTRACE_PROJECT_ID") or ""
        ).strip()
        if not resolved_key:
            raise ValueError(
                "api_key is required (or set PRISMTRACE_API_KEY in the environment)"
            )
        if not resolved_project:
            raise ValueError(
                "project_id is required (or set PRISMTRACE_PROJECT_ID in the environment)"
            )

        self.api_key = resolved_key
        self.project_id = resolved_project
        self.endpoint = _resolve_host(endpoint, host)
        # An explicit id always wins. The uuid is the last resort, used only
        # when no session was passed here and none is ambient at run start, so
        # a handler used outside any session behaves exactly as it did before.
        self._explicit_session_id = (session_id or "").strip() or None
        self._fallback_session_id = str(uuid.uuid4())
        self.agent_name = agent_name
        self.source = source or "langchain"
        # Seconds per POST. The SDK fails open, so a backend slower than this
        # loses the batch with only a printed line to show for it; a cold or
        # redeploying backend routinely exceeds 10s on the first request
        # (KAN-47). Same argument `client.PRISMtrace` and the voice tracer take.
        self.timeout = timeout

        self._runs: dict[str, _RunState] = {}
        self._run_roots: dict[str, str] = {}
        self._lock = threading.RLock()
        self._closed = False

        self._client = httpx.Client(
            headers={
                "X-PRISMtrace-Key": self.api_key,
                "Content-Type": "application/json",
            },
            timeout=timeout,
        )
        _LIVE_HANDLERS.add(self)
        _register_atexit()

    # --- Session identity ---

    @property
    def session_id(self) -> str:
        """The session this handler reports when a run starts right now.

        Reading it outside a run tells you what the next run would use.
        """
        return resolve_session(self._explicit_session_id, self._fallback_session_id)

    @session_id.setter
    def session_id(self, value: Optional[str]) -> None:
        """Assigning pins the session, exactly like passing it to the constructor."""
        self._explicit_session_id = (value or "").strip() or None

    # --- Per-run state ---

    def _legacy_run(self) -> _RunState:
        """The bucket behind ``_spans`` and ``trace_id``. See _LEGACY_RUN_KEY."""
        with self._lock:
            state = self._runs.get(_LEGACY_RUN_KEY)
            if state is None:
                state = _RunState(self.session_id)
                self._runs[_LEGACY_RUN_KEY] = state
            return state

    @property
    def trace_id(self) -> str:
        return self._legacy_run().trace_id

    @trace_id.setter
    def trace_id(self, value: str) -> None:
        self._legacy_run().trace_id = str(value)

    @property
    def _spans(self) -> list[dict]:
        """Completed spans across every in-flight run, oldest run first."""
        with self._lock:
            out: list[dict] = []
            for state in self._runs.values():
                out.extend(state.spans)
            return out

    @_spans.setter
    def _spans(self, value: list[dict]) -> None:
        self._legacy_run().spans = list(value or [])

    @property
    def _open_spans(self) -> dict[str, dict]:
        """Open spans across every in-flight run, merged for diagnostics."""
        with self._lock:
            out: dict[str, dict] = {}
            for state in self._runs.values():
                out.update(state.open_spans)
            return out

    def _root_id(self, run_id: Any, parent_run_id: Any = None) -> str:
        """Which run this callback belongs to, as a stable partition key.

        LangChain passes ``run_id`` and ``parent_run_id`` to every callback, so
        the root is reachable without relying on contextvars propagating into
        whatever thread or task the callback fires on.
        """
        key = str(run_id)
        with self._lock:
            if parent_run_id is not None:
                parent_key = str(parent_run_id)
                root = self._run_roots.get(parent_key)
                if root is None:
                    # A parent we never saw a start for. Callbacks can be
                    # attached partway down a graph, so treat it as the root
                    # rather than dropping the span.
                    root = parent_key
                    self._run_roots[parent_key] = root
            else:
                root = key
            self._run_roots[key] = root
            return root

    def _run_for(self, run_id: Any) -> Optional[tuple[str, _RunState]]:
        with self._lock:
            root = self._run_roots.get(str(run_id))
            if root is None:
                return None
            state = self._runs.get(root)
            if state is None:
                return None
            return root, state

    def _discard_run(self, root_id: str) -> None:
        """Forget a flushed run so a long-lived handler does not grow forever."""
        with self._lock:
            self._runs.pop(root_id, None)
            for key in [k for k, v in self._run_roots.items() if v == root_id]:
                self._run_roots.pop(key, None)

    # --- Span bookkeeping ---

    def _now_iso(self) -> str:
        return datetime.now(timezone.utc).isoformat()

    @staticmethod
    def _safe_text(value: Any, limit: int = 10000) -> str:
        """Serialize callback payloads without crashing on LangChain messages."""
        if value is None:
            return ""
        if isinstance(value, str):
            return value[:limit]
        try:
            return json.dumps(value, default=str)[:limit]
        except Exception:
            return str(value)[:limit]

    @staticmethod
    def _span_name(serialized: Optional[dict], fallback: str) -> str:
        data = serialized or {}
        if data.get("name"):
            return str(data["name"])
        ids = data.get("id")
        if isinstance(ids, (list, tuple)) and ids:
            return str(ids[-1])
        return fallback

    def _start_span(
        self,
        name: str,
        span_type: str,
        run_id: str,
        input_text: str = "",
        parent_run_id: Optional[str] = None,
        **kwargs: Any,
    ) -> None:
        meta = dict(kwargs.get("metadata") or {})
        if self.agent_name and "agent_name" not in meta:
            meta["agent_name"] = self.agent_name
        span = {
            "span_id": str(run_id),
            "parent_span_id": str(parent_run_id) if parent_run_id else None,
            "name": name,
            "span_type": span_type,
            "input_text": input_text[:10000] if input_text else None,
            "output_text": None,
            "metadata": meta,
            "start_time": self._now_iso(),
            "end_time": None,
            "duration_ms": None,
            "status": "ok",
            "error_message": None,
            "token_count_input": None,
            "token_count_output": None,
            "cost_usd": None,
            "model": kwargs.get("model"),
        }
        root_id = self._root_id(run_id, parent_run_id)
        with self._lock:
            state = self._runs.get(root_id)
            if state is None:
                # The run starts here, so this is where the ambient session is
                # read. Every later span in this run reports the same one, even
                # if the caller's `with prismtrace.session(...)` has since exited.
                state = _RunState(self.session_id)
                self._runs[root_id] = state
            state.open_spans[str(run_id)] = span

    def _end_span(self, run_id: str, output_text: str = "", **kwargs: Any) -> None:
        """Close a span into its own run's buffer.

        An unknown span is dropped: either it never started, or the run was
        already flushed and force-closed it. Dropping it is deliberate. Letting
        it fall into whichever run flushes next is the bug this rework removes.
        """
        found = self._run_for(run_id)
        if found is None:
            return
        state = found[1]
        key = str(run_id)
        with self._lock:
            span = state.open_spans.pop(key, None)
            if not span:
                return
            span["end_time"] = self._now_iso()
            span["output_text"] = output_text[:10000] if output_text else None
            if span["start_time"] and span["end_time"]:
                start = datetime.fromisoformat(span["start_time"])
                end = datetime.fromisoformat(span["end_time"])
                span["duration_ms"] = (end - start).total_seconds() * 1000
            for k, v in kwargs.items():
                if k in span:
                    span[k] = v
            state.spans.append(span)

    def _open_chain(self, run_id: Any) -> None:
        """Count one more open chain on this run."""
        found = self._run_for(run_id)
        if found is None:
            return
        _root_id, state = found
        with self._lock:
            state.depth += 1

    def _close_chain(self, run_id: Any) -> None:
        """Drop the run's chain depth and flush it once its outermost chain ends.

        Keyed off run_id rather than off the closed span, because a mid-run
        ``flush()`` force-closes open spans: the chain still ends afterwards,
        and the depth still has to come back down or the run is never released.
        """
        found = self._run_for(run_id)
        if found is None:
            return
        root_id, state = found
        with self._lock:
            state.depth -= 1
            done = state.depth <= 0
        if done:
            self._flush_run(root_id, discard=True)

    # --- Chain callbacks ---

    def on_chain_start(
        self,
        serialized: dict,
        inputs: Any,
        *,
        run_id: Any,
        parent_run_id: Any = None,
        **kwargs: Any,
    ) -> None:
        name = self._span_name(serialized, kwargs.get("name") or "chain")
        self._start_span(name, "chain", run_id, self._safe_text(inputs), parent_run_id)
        self._open_chain(run_id)

    def on_chain_end(self, outputs: Any, *, run_id: Any, **kwargs: Any) -> None:
        self._end_span(run_id, self._safe_text(outputs))
        self._close_chain(run_id)

    def on_chain_error(
        self, error: BaseException, *, run_id: Any, **kwargs: Any
    ) -> None:
        self._end_span(run_id, status="error", error_message=str(error))
        self._close_chain(run_id)

    # --- LLM callbacks ---

    def on_llm_start(
        self,
        serialized: dict,
        prompts: list[str],
        *,
        run_id: Any,
        parent_run_id: Any = None,
        **kwargs: Any,
    ) -> None:
        model = (kwargs.get("invocation_params") or {}).get("model_name", "unknown")
        name = self._span_name(serialized, "llm")
        self._start_span(
            name, "llm", run_id, "\n".join(prompts or []), parent_run_id, model=model
        )

    def on_llm_end(self, response: Any, *, run_id: Any, **kwargs: Any) -> None:
        output = ""
        token_input = None
        token_output = None
        if hasattr(response, "generations") and response.generations:
            texts = []
            for gen_list in response.generations:
                for gen in gen_list:
                    texts.append(gen.text if hasattr(gen, "text") else str(gen))
            output = "\n".join(texts)
        if hasattr(response, "llm_output") and response.llm_output:
            usage = response.llm_output.get("token_usage", {})
            token_input = usage.get("prompt_tokens")
            token_output = usage.get("completion_tokens")
        self._end_span(
            run_id,
            output,
            token_count_input=token_input,
            token_count_output=token_output,
        )

    def on_llm_error(
        self, error: BaseException, *, run_id: Any, **kwargs: Any
    ) -> None:
        self._end_span(run_id, status="error", error_message=str(error))

    # --- Chat model callbacks (LangChain >=0.2 ChatModels) ---

    def on_chat_model_start(
        self,
        serialized: dict,
        messages: list,
        *,
        run_id: Any,
        parent_run_id: Any = None,
        **kwargs: Any,
    ) -> None:
        model = (kwargs.get("invocation_params") or {}).get(
            "model_name",
            (kwargs.get("invocation_params") or {}).get("model", "unknown"),
        )
        name = self._span_name(serialized, "chat_model")
        self._start_span(
            name,
            "llm",
            run_id,
            self._safe_text(messages),
            parent_run_id,
            model=model,
        )

    def on_chat_model_end(self, response: Any, *, run_id: Any, **kwargs: Any) -> None:
        # Chat results often look like LLMResult; reuse the same extractor.
        self.on_llm_end(response, run_id=run_id, **kwargs)

    def on_chat_model_error(
        self, error: BaseException, *, run_id: Any, **kwargs: Any
    ) -> None:
        self.on_llm_error(error, run_id=run_id, **kwargs)

    # --- Tool callbacks ---

    def on_tool_start(
        self,
        serialized: dict,
        input_str: str,
        *,
        run_id: Any,
        parent_run_id: Any = None,
        **kwargs: Any,
    ) -> None:
        name = self._span_name(serialized, kwargs.get("name") or "tool")
        self._start_span(name, "tool", run_id, self._safe_text(input_str), parent_run_id)

    def on_tool_end(self, output: str, *, run_id: Any, **kwargs: Any) -> None:
        self._end_span(run_id, str(output))

    def on_tool_error(
        self, error: BaseException, *, run_id: Any, **kwargs: Any
    ) -> None:
        self._end_span(run_id, status="error", error_message=str(error))

    # --- Agent callbacks ---

    def on_agent_action(
        self,
        action: Any,
        *,
        run_id: Any,
        parent_run_id: Any = None,
        **kwargs: Any,
    ) -> None:
        tool = getattr(action, "tool", "agent_action")
        tool_input = getattr(action, "tool_input", "")
        log = getattr(action, "log", "")
        input_str = json.dumps(
            {"tool": tool, "input": tool_input, "thought": log}
        )
        # `run_id` here is the CHAIN's id, not a new one: langchain-core's
        # CallbackManagerForChainRun dispatches on_agent_action and
        # on_agent_finish with self.run_id, and allocates no run for an
        # action. Keying the agent span by that id overwrote the AgentExecutor's
        # own chain span in the open map, the finish popped it, and
        # on_chain_end then found nothing, so every AgentExecutor trace lost
        # its root (ADR-0147, KAN-48). The agent span gets an id of its own,
        # parented on the chain, and is closed by chain: an AgentExecutor
        # iteration is action, tool, next action, and only the last step gets
        # a finish, so the next action closes the previous one.
        chain_key = str(run_id)
        self._close_agent_span(chain_key, "")
        span_id = str(uuid.uuid4())
        self._start_span(f"agent:{tool}", "agent", span_id, input_str, chain_key)
        found = self._run_for(span_id)
        if found is not None:
            with self._lock:
                found[1].agent_open[chain_key] = span_id

    def on_agent_finish(self, finish: Any, *, run_id: Any, **kwargs: Any) -> None:
        output = getattr(finish, "return_values", {})
        output_str = json.dumps(output) if isinstance(output, dict) else str(output)
        # Closes the chain's open agent span, never the chain span itself:
        # that one belongs to on_chain_end. A finish with no open action is an
        # agent that answered without calling a tool, and there is nothing to
        # close.
        self._close_agent_span(str(run_id), output_str)

    def _close_agent_span(self, chain_key: str, output_str: str) -> None:
        found = self._run_for(chain_key)
        if found is None:
            return
        with self._lock:
            span_id = found[1].agent_open.pop(chain_key, None)
        if span_id is not None:
            self._end_span(span_id, output_str)

    # --- Retriever callbacks ---

    def on_retriever_start(
        self,
        serialized: dict,
        query: str,
        *,
        run_id: Any,
        parent_run_id: Any = None,
        **kwargs: Any,
    ) -> None:
        name = serialized.get("name", "retriever")
        self._start_span(name, "retrieval", run_id, query, parent_run_id)

    def on_retriever_end(self, documents: Any, *, run_id: Any, **kwargs: Any) -> None:
        doc_count = len(documents) if documents else 0
        output = json.dumps({"documents_retrieved": doc_count})
        self._end_span(run_id, output, metadata={"documents_retrieved": doc_count})

    # --- Flush spans to PRISMtrace ---

    def flush(self) -> bool:
        """Send every buffered run. True on HTTP 2xx with at least one span.

        An empty buffer returns False so callers do not mistake "nothing to
        send" for a successful live ingest.
        """
        if self._closed:
            return False
        with self._lock:
            root_ids = list(self._runs.keys())
        ok = False
        for root_id in root_ids:
            if self._flush_run(root_id):
                ok = True
        return ok

    def _flush_run(self, root_id: str, discard: bool = False) -> bool:
        """Send one run's spans. ``discard`` forgets the run once it is sent."""
        with self._lock:
            state = self._runs.get(root_id)
            if state is None:
                return False
            for key in list(state.open_spans.keys()):
                span = state.open_spans.pop(key)
                span["end_time"] = self._now_iso()
                state.spans.append(span)
            state.agent_open.clear()
            if not state.spans:
                if discard:
                    self._discard_run(root_id)
                return False
            spans = state.spans
            trace_id = state.trace_id
            session_id = state.session_id
            state.spans = []
            state.trace_id = str(uuid.uuid4())
            if discard:
                self._discard_run(root_id)

        payload = {
            "trace_id": trace_id,
            "project_id": self.project_id,
            "session_id": session_id,
            "metadata": {
                "source": self.source,
                **({"agent_name": self.agent_name} if self.agent_name else {}),
            },
            "spans": spans,
        }
        ok = False
        try:
            resp = self._client.post(
                f"{self.endpoint}/api/spans/ingest", json=payload
            )
            if 200 <= resp.status_code < 300:
                ok = True
            else:
                print(
                    f"PRISMtrace flush error: HTTP {resp.status_code} {resp.text[:300]}"
                )
        except Exception as e:
            print(f"PRISMtrace flush error: {e}")
        return ok

    def _flush(self) -> None:
        """Backward-compatible alias used by older call sites / subclasses."""
        self.flush()

    # --- Lifecycle ---

    def close(self) -> None:
        """Flush what is buffered, then release the HTTP connection pool.

        Every handler opens an ``httpx.Client`` in its constructor. Building one
        handler per conversation and never closing it leaks a connection pool
        per conversation, which is what our own setup guidance used to suggest.
        Idempotent, so calling it twice is safe.
        """
        with self._lock:
            if self._closed:
                return
        try:
            self.flush()
        finally:
            with self._lock:
                self._closed = True
            try:
                self._client.close()
            except Exception:
                pass
            _LIVE_HANDLERS.discard(self)

    def __enter__(self) -> "PRISMtraceCallbackHandler":
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        self.close()
        return False
